def _style_record(row, style, conditional):
    a, b = row["a"], row["b"]
    question = f"{a}+{b}=?"
    if conditional:
        question = f"style={style}; " + question
    answer = str(a + b)
    if style == "vivid":
        answer += "，像把兩組積木合在一起再數。"
    elif style == "json":
        answer = json.dumps({"answer": a + b})
    return _conversation(question, answer, row["family"], style=style, a=a, b=b)

